// This is the existing game menu and economy, not a real branch ordering service.
export function cafeSelection(menu,id){return menu.find(item=>item.id===id)||null;}
export function coffeeGuideHTML(s,selected,receipt,{E,esc}){
 const item=cafeSelection(E.COFFEE_MENU,selected),floor=E.FLOORPLANS[s.mallId].levels[s.floor||0],location=E.mallOf(s).name+' · '+floor;
 return `<div class="modal-body cafe-guide"><span class="eyebrow">COFFEE TERRACE · ${esc(location)}</span><h3>A little pause between shops.</h3><p>Choose something, review its game price and time, then pay when you’re ready. Browsing this menu pauses the clock and costs nothing.</p>${receipt?`<section class="cafe-receipt" role="status"><strong>${esc(receipt.name)} collected</strong><p>${E.money(receipt.paid)} paid · day ${receipt.day} · ${receipt.minutes} game minutes.</p></section>`:''}<div class="cafe-options" role="group" aria-label="Coffee and pastry choices">${E.COFFEE_MENU.map(d=>`<button class="cafe-option" data-action="coffee-select" data-id="${esc(d.id)}" aria-pressed="${selected===d.id}"><span aria-hidden="true">${d.emoji}</span><span><strong>${esc(d.name.replace(/^Starbucks /,''))}</strong><small>${d.category==='food'?'Pastry':d.id==='sb-cold'?'Cold coffee':'Hot coffee'} · ${d.minutes} min</small></span><b>${E.money(d.price)}</b></button>`).join('')}</div><section class="cafe-order-review" aria-label="Review your order" role="status">${item?`<h3>${esc(item.name)}</h3><p>${esc(item.description)}</p><div class="care-summary"><span>Total ${E.money(item.price)}</span><span>${item.minutes} game minutes</span><span>Up to +${item.energy} stamina</span>${item.hunger?`<span>Up to +${item.hunger} fullness</span>`:''}</div><p>Your wallet: <strong>${E.money(s.cash)}</strong>${s.cash>=item.price?` · after payment ${E.money(s.cash-item.price)}`:' · choose a lower price or take free water and a bench break.'}</p>`:'<p>Select a drink or pastry above to review the total. Nothing has been ordered yet.</p>'}</section><p class="hint">Drink and pastry names refer to Starbucks products. This original game counter uses simulated prices and recovery values; it does not represent a real Starbucks branch or supply real food. ${s.metrics.coffees} coffee orders across this save.</p><details><summary>Reference names & game service</summary><p>The espresso guide explains Caffè Latte, Flat White, Cappuccino and Caffè Americano. The game does not simulate drink customization or nutritional effects.</p><a href="https://about.starbucks.com/stories/2025/espresso-explained/" target="_blank" rel="noopener noreferrer">Official espresso reference ↗</a></details><button class="button secondary wide" data-action="close">Back to the terrace</button></div>`;
}

export function coffeeFooterHTML(s,selected,{E,esc}){const item=cafeSelection(E.COFFEE_MENU,selected);return `<div class="cafe-order-footer" role="group" aria-label="Payment review">${item?`<div aria-live="polite"><strong>${esc(item.name.replace(/^Starbucks /,''))}</strong><small>Total ${E.money(item.price)} · ${item.minutes} min · wallet ${E.money(s.cash)}</small></div><button class="button orange" data-action="coffee-order" data-id="${esc(item.id)}" ${s.cash<item.price?'disabled':''}>Pay ${E.money(item.price)}</button>`:'<span>Select a drink or pastry to review your order.</span>'}</div>`;}
